function validate([nums, k]) {
  if (nums.length < 1) return 'nums needs at least one value.';
  if (nums.some((v) => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value of nums is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > 1000000000) return 'k is an integer from 1 to 10^9.';
  return null;
}

