function countGood(nums, k) {
  const count = new Map();
  let pairs = 0;
  let left = 0;
  let answer = 0;
  for (let right = 0; right < nums.length; right++) {
    const value = nums[right];
    const before = count.get(value) ?? 0;
    pairs += before;
    count.set(value, before + 1);
    while (pairs >= k) {
      const removed = nums[left];
      const remaining = count.get(removed) - 1;
      count.set(removed, remaining);
      pairs -= remaining;
      left++;
    }
    answer += left;
  }
  return answer;
}

