function countGood(nums, k) {
  let total = 0;
  for (let start = 0; start < nums.length; start++) {
    for (let end = start; end < nums.length; end++) {
      let matching = 0;
      for (let i = start; i <= end; i++) {
        for (let j = i + 1; j <= end; j++) {
          if (nums[i] === nums[j]) matching++;
        }
      }
      if (matching >= k) total++;
    }
  }
  return total;
}

