  if (size === 'large') {
    const n = int(1500, 2000);
    const kinds = int(1, 60);
    const nums = Array.from({ length: n }, () => int(1, kinds) * 16127);
    const k = rand() < 0.1 ? int(1, 1000000000) : int(1, 40000);
    return [nums, k];
  }
  const n = int(1, 10);
  const kinds = int(1, 4);
  const base = rand() < 0.2 ? 999999990 : 0;
  const nums = Array.from({ length: n }, () => base + int(1, kinds));
  const k = rand() < 0.1 ? 1000000000 : int(1, 12);
  return [nums, k];
}
